/// <summary>
/// Return TAMRebateTable record from TAMRebateTrans
/// </summary>
/// <param name = "_forUpdate">Select for update</param>
/// <returns><c>TAMRebateTable</c> record</returns>
public TAMRebateTable METTAMRebateTable(boolean _forUpdate = false)
{
    return TAMRebateTable::find(this.RebateId, _forUpdate);
}

/// <summary>
/// Bug 281410: CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
/// After TAMRebateTrans are inserted, TAMRebateTransBasisTotal\distributeDateTransRebateAmount updates the rebateTrans.RebateAmount line 114
/// This setPostingAmount() is called just after that and before the update
/// </summary>
/// <param name = "_useClaimProcess">Use claim process</param>
public void setPostingAmount(boolean _useClaimProcess)
{
    if (this.metRebateDeal().METVolumetricTierDeal)
    {
        // Bug 293558: CB201- Volmetric rebate is ignoring Tier rate table
        // Remove the rebateId field from METTierRateTrans, instead use the deal id
        METTierRateTrans tierRateTrans = METTierRateTrans::find(this.metRebateDeal().Deal, this.RebateRefDate, TAMRebateDateTrans::find(this.RebateTransId).RebateTransactionType);

        if (tierRateTrans)
        {
            // Bug 281410: CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
            // Apply rounding when source transaction is created as per standard
            //_rebateTrans.RebateAmount = (_rebateTrans.RebateRefAmount * tierRateTrans.EligibleRebate)/100;
            this.RebateAmount = CurrencyExchangeHelper::amount((this.RebateRefAmount * tierRateTrans.EligibleRebate)/100, this.CurrencyCode);
        }            
    }  

    next setPostingAmount(_useClaimProcess);
}

/// <summary>
/// Bug 281410: CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
/// Method to retrieve the rebate deal from the transaction
/// </summary>
/// <param name = "_forupdate">Select for update</param>
/// <returns><c>TAMRebateDeal</c></returns>
public TAMRebateDeal metRebateDeal(boolean _forupdate = false)
{
    return TAMRebateDeal::find(TAMRebateDateTrans::find(this.RebateTransId).RebateDeal, _forupdate);
}

/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// Could not extend TAMRebateDateTrans.delete() as Hookable(false) nor cascadeDeleteRebateTrans as internal
/// When a rebateTrans is deleted and linked to METRebateScanSupplierTable, we need to update the corresponding flags
/// So we can reuse the transactions in the same or another rebate
/// </summary>
public void delete()
{
    ttsbegin;

    // Update external sales data provision or rebate processed to No
    METRebateScanSupplierTable::updateProcessedFlags(TAMRebateDateTrans::find(this.RebateTransId).RebateTransactionType, NoYes::No, this.RebateTransId, this.RefRecId);

    next delete();        

    ttscommit;        
}

/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// </summary>
/// <param name = "_externalSalesData"><t>METRebateScanSupplierTable</t></param>
public void metInitFromExternalSalesData(METRebateScanSupplierTable _externalSalesData)
{
    // Bug 295229: CB705- Unable to post provision for a rebate deal.
    // TAMRebateTrans.Vendor account was not set
    if (_externalSalesData.CustAccount)
    {  
        this.RebateRefAccount   = _externalSalesData.CustAccount;
    }
    else
    {
        this.RebateRefAccount   = _externalSalesData.VendAccount;
    }

    this.RebateRefId        = _externalSalesData.TransactionNumber;
    this.CurrencyCode       = _externalSalesData.CurrencyCode;
    this.ItemId             = _externalSalesData.ItemId;
    this.RebateRefQty       = _externalSalesData.SalesQty;
    this.RefUnitId          = _externalSalesData.UnitOfMeasure;
}

public void insert()
{
    TAMRebateDeal rebateDeal = this.metRebateDeal();

    if (rebateDeal.METAggregatedBy == METConstants::aggregateByCustomer
    && this.METAggregatedStr == METConstants::emptyString)
    {
        this.METAggregatedStr = this.RebateRefAccount;
    }

    next insert();
}
